- t2: mutex_lock main::a; mutex_lock main::b; mutex_unlock main::b; mutex_unlock main::a
- t3: mutex_lock main::c; mutex_lock main::d; mutex_unlock main::d; mutex_unlock main::c
- t4: mutex_lock main::c; mutex_lock main::d; mutex_unlock main::d; mutex_unlock main::c
- main: start [main::t1, main::t2, main::t3, main::t4]

