use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let permit = s.acquire();
    // Work is done while holding the permit
    drop(permit);
}

fn w2(s: Arc<Semaphore>) {
    let permit = s.acquire();
    // Work is done while holding the permit
    drop(permit);
}

fn w3(s: Arc<Semaphore>) {
    let permit = s.acquire();
    // Work is done while holding the permit
    drop(permit);
}

fn main() {
    let s = Semaphore::new(1);

    let h1 = thread::spawn({
        let s = Arc::clone(&s);
        move || w1(s)
    });

    let h2 = thread::spawn({
        let s = Arc::clone(&s);
        move || w2(s)
    });

    let h3 = thread::spawn({
        let s = Arc::clone(&s);
        move || w3(s)
    });

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    println!("DONE done=1");
}
```

