use std::sync::{Arc, Mutex};

fn compute() -> i32 {
    let tmp = 1 + 1;
    tmp
}

fn w1(m: Arc<Mutex<i32>>) {
    let mut guard = m.lock().unwrap();
    let _ = compute();
    *guard += 1;
}

fn w2(m: Arc<Mutex<i32>>) {
    let mut guard = m.lock().unwrap();
