    *guard += 1;
}

fn main() {
    let acc = Arc::new(Mutex::new(0));

    let m1 = Arc::clone(&acc);
    let h1 = std::thread::spawn(move || {
        w1(m1);
    });

    let m2 = Arc::clone(&acc);
    let h2 = std::thread::spawn(move || {
        w2(m2);
    });

    h1.join().unwrap();
    h2.join().unwrap();

    let done = *acc.lock().unwrap();
